312	async function resolveModelContextWindowTokens(modelId: string): Promise<number> {
313	  const cached = modelContextWindowCache.get(modelId);
314	  if (cached) return cached;
315	  const pending = (async () => {
316	    const [rawProvider, ...modelParts] = modelId.split(":");
