323	        return Math.floor(contextWindow);
324	      }
325	    } catch {
326	      // Metadata may lag brand-new model IDs; keep runner behavior stable.
327	    }
328	    return resolveFallbackModelContextWindowTokens(modelId);
329	  })();
330	  modelContextWindowCache.set(modelId, pending);
