345	function buildProviderUsageTelemetry(
346	  usage: LlmUsage | undefined,
347	  contextWindowTokens: number,
348	  fallbackUsedTokens: number,
349	) {
350	  const inputTokens = readUsageTokenCount(usage, [
351	    "inputTokens",
352	    "promptTokens",
353	    "prompt_tokens",
354	  ]);
355	  const outputTokens = readUsageTokenCount(usage, [
356	    "outputTokens",
357	    "completionTokens",
358	    "completion_tokens",
359	  ]);
360	  const totalTokens = readUsageTokenCount(usage, ["totalTokens", "total_tokens"]);
361	  const reasoningTokens = readUsageTokenCount(usage, [
362	    "reasoningTokens",
363	    "reasoning_tokens",
364	  ]);
365	  const cachedInputTokens = readUsageTokenCount(usage, [
366	    "cachedInputTokens",
367	    "cachedPromptTokens",
368	    "cached_input_tokens",
369	    "cached_prompt_tokens",
370	  ]);
371	  const usedTokens = inputTokens ?? fallbackUsedTokens;
372	  const utilizationPct =
373	    contextWindowTokens > 0 ? Math.min(100, (usedTokens / contextWindowTokens) * 100) : 0;
374	  return {
375	    usageSource: inputTokens !== undefined ? "provider" : "estimate",
376	    estimatedUsedTokens: usedTokens,
377	    estimatedAvailableTokens: Math.max(0, contextWindowTokens - usedTokens),
378	    utilizationPct: Math.round(utilizationPct * 100) / 100,
379	    ...(inputTokens !== undefined ? { inputTokens } : {}),
380	    ...(outputTokens !== undefined ? { outputTokens } : {}),
381	    ...(totalTokens !== undefined ? { totalTokens } : {}),
382	    ...(reasoningTokens !== undefined ? { reasoningTokens } : {}),
383	    ...(cachedInputTokens !== undefined ? { cachedInputTokens } : {}),
384	  };
