import { existsSync, mkdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { resolveSkillRoots } from "@orgops/skills";
import { stopAllRunningProcesses } from "./tools/shell";
import { createChannelLoopManager } from "./channel-loop";
import { shouldHandleEventForAgent } from "./event-routing";
import { createMaintenanceLoop } from "./maintenance-loop";
import { stopAllRlmChildren } from "./rlm-process";
import { createRunnerState } from "./runner/state";
import { createRunnerApi } from "./runner/api";
import {
  clearAgentIntentWatch,
  collectDueIntentTimeouts,
  ingestIntentEvents,
} from "./intent-watchdog";
import {
  agentChannelKey,
  shouldSuppressProcessLifecycleTrigger,
} from "./turn-trigger-filter";
import {
  createTurnExecutor,
  reconcileLateInjectedMessages,
  resolveAgentClassicMaxModelSteps,
  resolveAgentLlmCallTimeoutMs,
  resolveAgentMemoryContextMode,
} from "./turn-executor";
import {
  ensureWrappedAgentReady,
  stopAllWrappedRuntimes,
  stopWrappedAgentRuntime,
const state = createRunnerState();
const api = createRunnerApi({
  apiUrl: API_URL,
  runnerToken: process.env.ORGOPS_RUNNER_TOKEN ?? "dev-runner-token",
  heartbeatIntervalMs: HEARTBEAT_INTERVAL_MS,
  runnerIdFile: RUNNER_ID_FILE,
  runnerState: state,
});
const handleTurn = createTurnExecutor({
  projectRoot: PROJECT_ROOT,
  skillRoots: SKILL_ROOTS,
  llmCallTimeoutMs: LLM_CALL_TIMEOUT_MS,
  runtimeAuth: {
    apiBaseUrl: API_URL,
    runnerToken: process.env.ORGOPS_RUNNER_TOKEN ?? "dev-runner-token",
  },
  api: {
    apiFetch: api.apiFetch,
    emitEvent: api.emitEvent,
    listChannels: api.listChannels,
    getChannelRecord: api.getChannelRecord,
    getChannelParticipationValidationError: api.getChannelParticipationValidationError,
    getPackageSecretsEnv: api.getPackageSecretsEnv,
    ensureLifecycleChannel: api.ensureLifecycleChannel,
  },
});
const maintenanceLoop = createMaintenanceLoop({
  listChannels: api.listChannels,
  getPackageSecretsEnv: api.getPackageSecretsEnv,
  apiFetch: api.apiFetch,
  channelRecentMemoryIntervalMs: CHANNEL_RECENT_MEMORY_INTERVAL_MS,
  channelFullMemoryIntervalMs: CHANNEL_FULL_MEMORY_INTERVAL_MS,
  crossRecentMemoryIntervalMs: CROSS_RECENT_MEMORY_INTERVAL_MS,
  crossFullMemoryIntervalMs: CROSS_FULL_MEMORY_INTERVAL_MS,
});

import { describe, expect, it } from "vitest";
import { createRunnerTools } from "./tools";
import { executeTool } from "./tools";
import {
  reconcileLateInjectedMessages,
  buildModelMessages,
  resolveAgentClassicMaxModelSteps,
  resolveAgentMemoryContextMode,
  resolveAgentLlmCallTimeoutMs,
  selectRecentDeltaEventsForPrompt,
  shouldHandleEvent,
} from "./runner";
import { stopAllRunningProcesses } from "./tools/shell";
import type { Agent, Event } from "./types";

describe("agent runner", () => {
  it("resolves per-agent timeout and model-step overrides with sane defaults", () => {
    const baseAgent: Agent = {
      name: "tester",
      systemInstructions: "",
      soulPath: "",
      workspacePath: "/tmp",
      modelId: "openai:gpt-4o-mini",
      desiredState: "RUNNING",
      runtimeState: "RUNNING",
    };

    expect(resolveAgentLlmCallTimeoutMs(baseAgent)).toBe(10800000);
    expect(resolveAgentClassicMaxModelSteps(baseAgent)).toBe(100);
    expect(resolveAgentMemoryContextMode(baseAgent)).toBe("PER_CHANNEL_CROSS_CHANNEL");

    expect(
      resolveAgentLlmCallTimeoutMs({ ...baseAgent, llmCallTimeoutMs: 180_000 }),
    ).toBe(180000);
    expect(
      resolveAgentClassicMaxModelSteps({
        ...baseAgent,
        classicMaxModelSteps: 250,
      }),
    ).toBe(250);

    expect(
      resolveAgentLlmCallTimeoutMs({ ...baseAgent, llmCallTimeoutMs: 0 }),
    ).toBe(10800000);
    expect(
      resolveAgentClassicMaxModelSteps({
        ...baseAgent,
        classicMaxModelSteps: -1,
      }),
    ).toBe(100);
    expect(
      resolveAgentMemoryContextMode({
        ...baseAgent,
        memoryContextMode: "FULL_CHANNEL_EVENTS",
      }),
    ).toBe("FULL_CHANNEL_EVENTS");
    expect(
      resolveAgentMemoryContextMode({
        ...baseAgent,
        memoryContextMode: "OFF",
      }),
    ).toBe("OFF");
    expect(
      resolveAgentMemoryContextMode({
        ...baseAgent,
        memoryContextMode: "invalid" as any,
      }),
    ).toBe("PER_CHANNEL_CROSS_CHANNEL");
  });

  it("reconciles same turn when late injected channel events arrive", async () => {
    const agent: Agent = {
      name: "tester",
      systemInstructions: "",
      soulPath: "",
      workspacePath: "/tmp",
      modelId: "openai:gpt-4o-mini",
      desiredState: "RUNNING",
      runtimeState: "RUNNING",
    };
    const seenEventIds = new Set<string>(["evt-trigger"]);
    const retryMessages: Array<{ role: "system" | "user"; content: string }> = [];
    const apiFetch = async () =>
      new Response(
        JSON.stringify([
          {
            id: "evt-tool",
            type: "tool.started",
            source: "agent:tester",
            channelId: "chan-1",
            payload: { tool: "shell_run" },
            createdAt: 1,
          },
          {
            id: "evt-process-started",
            type: "process.started",
            source: "system:process-runner",
            channelId: "chan-1",
            payload: { processId: "proc-1", targetAgentName: "tester" },
            createdAt: 2,
          },
        ] satisfies Event[]),
        {
          status: 200,
          headers: { "content-type": "application/json" },
        },
      );

    const hasLateMessages = await reconcileLateInjectedMessages({
      apiFetch,
      agent,
      channelId: "chan-1",
      seenEventIds,
      retryMessages,
      attempt: 1,
      maxAttempts: 3,
    });

    expect(hasLateMessages).toBe(true);
    expect(retryMessages).toHaveLength(2);
    expect(retryMessages[0]?.content).toContain('"type": "process.started"');
    expect(retryMessages[1]?.content).toContain("New channel events arrived");
    expect(seenEventIds.has("evt-process-started")).toBe(true);
    expect(seenEventIds.has("evt-tool")).toBe(true);

    const hasNewMessagesOnSecondPull = await reconcileLateInjectedMessages({
      apiFetch,
      agent,
      channelId: "chan-1",
      seenEventIds,
      retryMessages,
      attempt: 2,
      maxAttempts: 3,
    });
    expect(hasNewMessagesOnSecondPull).toBe(false);
  });

