  };
  if (options.env) {
    for (const key of PROVIDER_SECRET_ENV_KEYS) {
      if (!(key in options.env)) delete env[key];
    }
  }
  if (env.ORGOPS_LLM_STUB === "1") {
    return { text: "LLM stub response.", toolCalls: [], toolResults: [] };
