import { readFileSync, writeFileSync } from "node:fs";
import { arch, hostname, release } from "node:os";
import { ChannelRecord, isAgentSubscribed } from "../models/channel";
import type { Agent, Event } from "../types";
import type { RunnerState } from "./state";

type RunnerApiDeps = {
  apiUrl: string;
  runnerToken: string;
  heartbeatIntervalMs: number;
  runnerIdFile: string;
  runnerState: RunnerState;
};

type RunnerIdentityPayload = { runner?: { id?: string } };

let apiFetchRequestCounter = 0;

function getErrorSummary(error: unknown) {
  const err = error as
    | (Error & {
        code?: string;
        errno?: number | string;
        syscall?: string;
        cause?: unknown;
      })
    | undefined;
  const cause = err?.cause as
    | (Error & {
        code?: string;
        errno?: number | string;
        syscall?: string;
      })
    | undefined;
  return {
    message: err?.message ?? String(error),
    name: err?.name,
    code: err?.code,
    errno: err?.errno,
    syscall: err?.syscall,
    cause: cause
      ? {
          message: cause.message ?? String(cause),
          name: cause.name,
          code: cause.code,
          errno: cause.errno,
          syscall: cause.syscall,
        }
      : undefined,
  };
}

function readRunnerIdFromDisk(filePath: string): string | null {
  try {
    const value = readFileSync(filePath, "utf-8").trim();
    return value || null;
  } catch {
    return null;
  }
}
